#!/usr/bin/env bash
export NODE_PATH=/home/claude/pindeps/node_modules PATH=/home/claude/pyvenv/bin:$PATH
D=/home/claude/scratch/demo.sh; S=/tmp/standin.git
AR=accepted-results.json
$D 00-control "Control: nothing planted, simulated approved state" "all PASS incl. check-control 9/9; exit 0" "true" --fast --remote $S
$D D1-broken-assertion "Broken assertion" "test-cache FAIL; exit 1" "sed -i '10s/ok(J(T.mrp())===J(T.mrpCalc())/ok(J(T.mrp())!==J(T.mrpCalc())/' test-cache.js" --fast --remote $S
$D D2-removed-check "Removed check (count drop)" "test-po-edge FAIL COUNT DROPPED 35->34; exit 1 (check-protection also FAILs: test-po-edge.js is a protected file)" "sed -i '10d' test-po-edge.js" --fast --remote $S
$D D3-missing-helper "Missing prerequisite not on the accepted list (helper file deleted)" "golden ERROR, not BLOCKED; exit 1 (check-protection also FAILs: protected file missing)" "rm compare-snapshots.js" --fast --remote $S
DEMO_ENV="NODE_PATH=/home/claude/farm-noacorn" $D D4-missing-package "Pre-flight: Node package acorn missing (R13)" "pre-flight ERROR naming acorn; exit 1" "true  # nothing planted in the copy; NODE_PATH points to a package set without acorn" --fast --remote $S
DEMO_ENV="NODE_PATH=/home/claude/farm-badxlsx" $D D5-wrong-package-version "Pre-flight: package version differs from the recorded environment (R9/R10)" "pre-flight ERROR: xlsx 0.18.4 (recorded 0.18.5); exit 1" "true  # nothing planted in the copy; NODE_PATH has xlsx labelled 0.18.4" --fast --remote $S
$D R1a-count-lowered "Control file weakened: test7 accepted count lowered 118->117" "check-control FAIL (count LOWERED) and test7 FAIL (count above accepted); exit 1" "sed -i 's/\"file\": \"test7.js\", \"zones\": \"two\", \"tiers\": \[\"fast\", \"full\"\], \"accepted\": 118/\"file\": \"test7.js\", \"zones\": \"two\", \"tiers\": [\"fast\", \"full\"], \"accepted\": 117/' $AR" --fast --remote $S
$D R1b-new-limitation "Control file weakened: test-cache newly marked REDUCED" "check-control FAIL (status weakened); exit 1" "sed -i 's/\"file\": \"test-cache.js\", \"zones\": \"two\", \"tiers\": \[\"fast\", \"full\"\], \"accepted\": 15/&, \"status\": \"REDUCED\", \"full\": 30/' $AR" --fast --remote $S
$D R1c-checksum-removed "Control file weakened: protected line removed from checksums.txt" "check-control FAIL (approved line removed); exit 1" "sed -i '/tests\/test-cache.js$/d' checksums.txt" --fast --remote $S
$D R1d-runner-edited "Runner edited to always exit 0 (residual risk)" "check-control row FAIL (run-all.sh changed) BUT the edited runner exits 0; the approved guard run directly exits 1" "sed -i \"s/const code=n('FAIL')||n('ERROR')?1:0/const code=0/\" run-all.sh" --fast --remote $S
$D R1e-local-only-tag "Approved tag exists only locally, not on the remote" "check-control FAIL (local tag is not an approval); exit 1" "true  # remote /tmp/standin-notag.git has the protected refs but no approved tag" --fast --remote /tmp/standin-notag.git
$D R2a-count-rise "Check added without updating the accepted count (R2)" "test7 FAIL COUNT ABOVE ACCEPTED 118->119; exit 1 (check-protection also FAILs: test7.js protected)" "sed -i '0,/^ok(/s//ok(true,\"DEMO extra check\");ok(/' test7.js; grep -c 'DEMO extra check' test7.js" --fast --remote $S
$D R2b-approved-growth "Check added AND accepted count raised (growth)" "test7 PASS 119; check-control PASS with PENDING (raised 118->119); check-protection FAIL (test7.js protected); exit 1" "sed -i '0,/^ok(/s//ok(true,\"DEMO extra check\");ok(/' test7.js; sed -i 's/\"file\": \"test7.js\", \"zones\": \"two\", \"tiers\": \[\"fast\", \"full\"\], \"accepted\": 118/\"file\": \"test7.js\", \"zones\": \"two\", \"tiers\": [\"fast\", \"full\"], \"accepted\": 119/' $AR" --fast --remote $S
$D R3-blocked-file-missing "Blocked test file deleted (R3); tier widened to fast so the fast runner sees it" "test-fglt-note ERROR (file missing), not BLOCKED; check-control PENDING (tier added); exit 1" "rm test-fglt-note.js; sed -i 's/\"file\": \"test-fglt-note.js\", \"zones\": \"two\", \"tiers\": \[\"full\"\]/\"file\": \"test-fglt-note.js\", \"zones\": \"two\", \"tiers\": [\"full\", \"fast\"]/' $AR" --fast --remote $S
$D R4-reduced-without-reason "REDUCED count without its documented reason: test-phase1 skip message removed (R4); tier widened to fast" "test-phase1 FAIL (expected skip message not printed); exit 1" "sed -i 's/(C3_TREE not set: candidate 3 render comparison skipped)/(comparison skipped)/' test-phase1.js; sed -i 's/\"file\": \"test-phase1.js\", \"zones\": \"two\", \"tiers\": \[\"full\"\]/\"file\": \"test-phase1.js\", \"zones\": \"two\", \"tiers\": [\"full\", \"fast\"]/' $AR" --fast --remote $S
$D P1-protected-file-altered "Protected file altered: one byte appended to A1-TEST-RECORD.md (new R5 scope)" "check-protection FAIL naming A1-TEST-RECORD.md; exit 1" "printf ' ' >> A1-TEST-RECORD.md" --fast --remote $S
$D P2-reference-moved "Protected reference moved on the stand-in remote (main -> 40d3559)" "check-protection FAIL on refs/heads/main; exit 1" "git push -q -f /tmp/standin-p2.git 40d35598feed5ded9d6cb52f8508ceb070c3cfbb:refs/heads/main 2>/dev/null; git ls-remote /tmp/standin-p2.git refs/heads/main" --fast --remote /tmp/standin-p2.git
$D P3-remote-unreachable "Remote cannot be read" "check-protection ERROR and check-control ERROR (never PASS or BLOCKED); exit 1" "true" --fast --remote /tmp/does-not-exist.git
echo ALL-DONE
